// Update() は毎フレーム自動で呼ばれる（フレームレート依存）
component SimpleGameLoop {
    private Item player;
    private float timer = 0.0f;

    public void Update() {
        // deltaTime: 前フレームからの経過時間（秒）
        float deltaTime = hsSystemGetDeltaTime();
        timer += deltaTime;

        // 各フレーム実行（時間依存）
        HandleInput();
        UpdateGameState();
        UpdateUI();

        // 例：1秒ごとに何かを実行
        if(timer >= 1.0f) {
            OnTimerTick();
            timer = 0.0f;
        }
    }

    private void HandleInput() {
        // プレイヤー入力を処理
        if(hsInputClickButton(0, "W")) {
            player.MovePos(
                player.GetPos().AddNew(player.Forward()),
                0.1f, false, true
            );
        }
    }

    private void UpdateGameState() {
        // ゲーム状態を更新
        // フィジックス、AI、アニメーション等
    }

    private void UpdateUI() {
        // UI表示を更新（score等）
    }

    private void OnTimerTick() {
        // 時間経過での処理
        hsSystemWriteLine("Timer: " + timer);
    }
}

StateMachine_Beginner.code:
// 超シンプルなステートマシン（3状態・初心者向け）
// 【なぜシンプルか】
// - 状態が3つだけ（Ready → Playing → GameOver）
// - 各状態で「入る時」「毎フレーム」「出る時」を定義するだけ
// - 新しい状態を追加したい時も、パターンをコピーするだけで OK

interface IGameState {
    public void Enter();                // 状態に入る時（初期化）
    public void Update();               // 毎フレーム実行
    public IGameState GetNextState();   // 次の状態を返す
    public void Exit();                 // 状態から出る時（片付け）
}

// ========== 状態1: ゲーム開始待ち ==========
class GameStateReady : IGameState {
    public void Enter() {
        // Spaceキーを待つ状態に入る
        hsSystemWriteLine("[Ready] Spaceキーでゲーム開始");
    }

    public void Update() {
        // 毎フレーム実行（入力チェック）
    }

    public IGameState GetNextState() {
        // Spaceキーが押されたら Playing 状態へ
        if(hsInputClickButton(0, "Space")) {
            return new GameStatePlaying();
        }
        return null;  // 遷移しない
    }

    public void Exit() {
        hsSystemWriteLine("[Ready] ゲーム開始！");
    }
}

// ========== 状態2: ゲーム中 ==========
class GameStatePlaying : IGameState {
    private float gameTime = 0.0f;
    private float maxGameTime = 30.0f;  // 30秒でゲーム終了

    public void Enter() {
        // ゲーム開始時の初期化
        gameTime = 0.0f;
        hsSystemWriteLine("[Playing] ゲーム中（30秒）");
    }

    public void Update() {
        // 毎フレーム時間を足していく
        gameTime += hsSystemGetDeltaTime();

        // 3秒ごとに進捗を表示（デモ用）
        if((int)gameTime % 3 == 0) {
            hsSystemWriteLine("[Playing] 経過時間: " + (int)gameTime + "秒");
        }
    }

    public IGameState GetNextState() {
        // 30秒経過したら GameOver 状態へ
        if(gameTime >= maxGameTime) {
            return new GameStateGameOver();
        }
        return null;
    }

    public void Exit() {
        hsSystemWriteLine("[Playing] ゲーム終了!");
    }
}

// ========== 状態3: ゲームオーバー ==========
class GameStateGameOver : IGameState {
    public void Enter() {
        hsSystemWriteLine("[GameOver] Spaceキーでリスタート");
    }

    public void Update() {
        // 毎フレーム実行（リスタート待ち）
    }

    public IGameState GetNextState() {
        // Spaceキーが押されたら Ready 状態へ（リスタート）
        if(hsInputClickButton(0, "Space")) {
            return new GameStateReady();
        }
        return null;
    }

    public void Exit() {
        hsSystemWriteLine("[GameOver] リスタート開始");
    }
}

// ========== ゲーム全体を管理 ==========
component GameManager {
    private IGameState currentState;

    public GameManager() {
        // 最初は Ready 状態から開始
        currentState = new GameStateReady();
        currentState.Enter();
    }

    public void Update() {
        // 【重要】毎フレーム 2ステップを実行
        // ステップ1: 現在の状態を更新
        currentState.Update();

        // ステップ2: 次の状態があれば遷移
        IGameState nextState = currentState.GetNextState();
        if(nextState !== null) {
            currentState.Exit();      // 現在の状態を終了
            currentState = nextState; // 新しい状態に切り替え
            currentState.Enter();     // 新しい状態を開始
        }
    }
}

