// 超シンプル: 物体を掴んで運ぶ（初心者向け）
// 【なぜシンプルか】
// - 掴む・持つ・放すの 3ステップだけ
// - 【重要】SetPhysicsWorldPos() → ClearPhysicsWorldForce() のセットを覚えるだけ
// - 物理オブジェクトが落下しない仕組みはこれだけで十分
// 【パフォーマンス】
// - Vector3はメンバー変数で管理（毎フレーム再利用）
// - GetWorldPos()は1回だけ呼び出し
// - Update()内で最小限の処理

component SimpleCraneHand {
    private Item heldObject = null;  // 持っている物体
    private Vector3 handPos;  // 【最適化】毎フレーム再利用するVector3

    public void Update() {
        if(heldObject === null) return;  // 何も持っていない

        // 【重要】毎フレーム実行される (Update()のキモ！)
        // GetWorldPos()は1フレームに1回だけ呼び出し
        handPos = hsItemGetSelf().GetWorldPos();

        // ステップ1: 物体を手の位置に置く
        // SetPhysicsWorldPos()は物理ワールド座標を更新
        heldObject.SetPhysicsWorldPos("Body", handPos);

        // ステップ2: 落下をリセット (これを忘れると落ちる！)
        // 【重要】SetPhysicsWorldPos()の直後に必ず呼ぶ
        // ClearPhysicsWorldForce()は以下をリセット：
        // - 重力による加速度
        // - 衝突による速度
        // - 蓄積された運動量
        heldObject.ClearPhysicsWorldForce("Body");
    }

    // 物体に触れたら掴む
    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item item = hsItemGetByInstanceID(ItemInstanceID);
        if(item !== null && heldObject === null) {
            heldObject = item;
            // 【オプション】衝突判定を無効化（掴んだ物体が床をすり抜けるのを防止）
            // item.SetCollisionDetection(false);
            hsSystemWriteLine("掴んだ: " + item.GetName());
        }
    }

    // ボタンを押したら放す
    public void OnButtonPress() {
        if(heldObject !== null) {
            // 【重要】放す直前に力をリセット（物体が勢い良く落ちるのを防止）
            heldObject.ClearPhysicsWorldForce("Body");
            hsSystemWriteLine("放した: " + heldObject.GetName());
            heldObject = null;
        }
    }
}

