// 物体を掴んで運ぶパターン（クレーンゲーム類）
// 【前提】物体に Rigidbody コライダーが設定されていること

component ItemGrabber {
    private Item target;           // 掴むターゲット
    private string targetNodeName; // 物理計算の対象ノード
    private float grabOffset = 0.5f;

    public void GrabItem(Item itemToGrab) {
        if(itemToGrab === null) return;

        target = itemToGrab;
        // 掴んだ状態の初期化
        hsSystemWriteLine("Grabbed: " + target.GetName());
    }

    public void Update() {
        if(target === null) return;

        // 掴んだ物体をこのItemの位置に追従させる
        UpdateGrabbedObject();
    }

    private void UpdateGrabbedObject() {
        // 掴み手の位置を取得
        Vector3 grabPoint = hsItemGetSelf().GetWorldPos();
        grabPoint.y += grabOffset;  // 高さオフセット

        // 【重要】物理オブジェクトの位置を設定
        // SetPhysicsWorldPos(): 物理ワールド内で位置を設定
        target.SetPhysicsWorldPos(targetNodeName, grabPoint);

        // 【重要】物理計算をリセット（落下を防止）
        target.ClearPhysicsWorldForce(targetNodeName);

        // 掴み続けられているか判定
        if(hsInputClickButton(0, "MouseLeft") === false) {
            ReleaseItem();
        }
    }

    private void ReleaseItem() {
        if(target !== null) {
            hsSystemWriteLine("Released: " + target.GetName());
            target = null;  // 掴み解除
        }
    }
}

// 使用例：触れた物体を掴む
component CraneGimmick {
    private ItemGrabber grabber;

    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item collidedItem = hsItemGetByInstanceID(ItemInstanceID);
        if(collidedItem !== null) {
            // 衝突したItemを掴む
            grabber.GrabItem(collidedItem);
        }
    }
}

