// 【拡張版】MovePos() の使い方：スムーズな移動とアニメーション
component SmoothMovement {
    private Item player;

    public void MoveToTarget(Vector3 targetPos) {
        // 現在位置から目標位置までの距離を計算
        Vector3 currentPos = player.GetPos();
        float distance = hsMathLength(targetPos.AddNew(currentPos.Inverse()));

        // 距離に応じた移動時間を計算（移動速度: 5m/s）
        float duration = distance / 5.0f;

        // スムーズに移動（duration秒かけて targetPos へ）
        // 第3引数: local 座標か world 座標か
        // 第4引数: true = アニメーション中に他の処理をスキップ
        player.MovePos(targetPos, duration, false, true);

        // 移動完了を待つ（Update内で確認）
        // if(!player.IsMoving()) { /* 移動完了 */ }
    }

    public void Update() {
        // キー入力で移動
        if(hsInputClickButton(0, "G")) {
            Vector3 targetPos = makeVector3(10.0f, 0.0f, 5.0f);
            MoveToTarget(targetPos);
        }

        // 移動中の状態確認
        if(player.IsMoving()) {
            hsSystemWriteLine("Moving...");
        } else {
            hsSystemWriteLine("Stopped.");
        }
    }
}

