// 【比較版】SetPos() vs SetPhysicsWorldPos() の使い分け
component PhysicsComparison {
    private Item staticObject;    // 物理演算なし
    private Item physicsObject;   // 物理演算有り

    public void Update() {
        // ケース1: 通常のオブジェクト（物理演算不要）
        // 例：UIオブジェクト、装飾品
        if(hsInputClickButton(0, "1")) {
            Vector3 newPos = makeVector3(5.0f, 0.0f, 0.0f);
            staticObject.SetPos(newPos, false);
            hsSystemWriteLine("SetPos: Object moved immediately");
        }

        // ケース2: 物理演算オブジェクト（Rigidbody付き）
        // 例：投げる、落とす、掴む
        if(hsInputClickButton(0, "2")) {
            Vector3 newPos = makeVector3(5.0f, 0.0f, 0.0f);
            // SetPhysicsWorldPos で物理エンジンと同期
            physicsObject.SetPhysicsWorldPos("MainBody", newPos);
            // 重力やその他の力を保持（落下は続く）
        }

        // ケース3: 物理オブジェクトを「掴む」場合
        // 例：クレーンゲーム、手で持つ
        if(hsInputClickButton(0, "3")) {
            Vector3 grabPos = hsItemGet("Hand").GetWorldPos();
            physicsObject.SetPhysicsWorldPos("MainBody", grabPos);
            // 力をリセット（落下を止める）
            physicsObject.ClearPhysicsWorldForce("MainBody");
            hsSystemWriteLine("Grabbed: Physics reset");
        }
    }
}

Messaging_Beginner.code:
// 超シンプルなItem間メッセージング（初心者向け）
// 【なぜシンプルか】
// - メッセージの送受信がシンプルな「呼び出し・返答」パターン
// - 複雑な複数パラメータは不要、メッセージタイプだけで十分
// - 送信側と受信側の役割が明確に分かれている

// ========== 受信側: ドアを操作される側 ==========
component DoorComponent {
    private Item self;
    private bool isOpen = false;

    public DoorComponent() {
        self = hsItemGetSelf();
    }

    // ボタンからのメッセージを受け取る【ここが重要】
    public void OnReceiveMessage(HSMessage message) {
        string msgType = message.GetType();

        if(msgType == "OpenDoor") {
            OpenTheDoor();
        } else if(msgType == "CloseDoor") {
            CloseTheDoor();
        }
    }

    private void OpenTheDoor() {
        if(isOpen) return;  // 既に開いている

        isOpen = true;
        hsSystemWriteLine("ドアが開きました");
        self.MovePos(self.GetPos().AddNew(makeVector3(0, 0, 1)), 1.0f, false, true);
    }

    private void CloseTheDoor() {
        if(!isOpen) return;  // 既に閉じている

        isOpen = false;
        hsSystemWriteLine("ドアが閉じました");
        self.MovePos(self.GetPos().AddNew(makeVector3(0, 0, -1)), 1.0f, false, true);
    }
}

// ========== 送信側: ボタンを押される側 ==========
component ButtonComponent {
    private Item targetDoor;

    public ButtonComponent() {
        targetDoor = hsItemGet("Door");  // 操作対象の扉を見つける
    }

    // ボタンに触れた時
    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item player = hsItemGetByInstanceID(ItemInstanceID);
        if(player !== null) {
            SendMessageToDoor("OpenDoor");
        }
    }

    private void SendMessageToDoor(string command) {
        if(targetDoor === null) return;

        // メッセージ作成（タイプだけ指定）
        HSMessage msg = hsCreateSelfMessage(command);

        // メッセージ送信（ドアの OnReceiveMessage() が呼ばれる）
        targetDoor.SendMessage(msg);

        hsSystemWriteLine("ボタン: " + command + " メッセージを送信");
    }
}

