// Item 間のメッセージングパターン
// ボタンを押すと扉が開く、という例

component DoorController {
    private Item self;
    private bool isOpen = false;

    public DoorController() {
        self = hsItemGetSelf();
        // メッセージを受け取るために自身を登録（自動）
    }

    // メッセージ受信処理（自動で呼ばれる）
    public void OnReceiveMessage(HSMessage message) {
        string messageType = message.GetType();

        if(messageType == "OpenDoor") {
            // 「扉を開く」メッセージを受け取った
            OnOpenDoor(message);
        } else if(messageType == "CloseDoor") {
            // 「扉を閉じる」メッセージを受け取った
            OnCloseDoor(message);
        }
    }

    private void OnOpenDoor(HSMessage msg) {
        if(isOpen) return;  // 既に開いている

        isOpen = true;
        hsSystemWriteLine("Door: Opening...");

        // 扉をY軸で回転（開く）
        self.MovePos(
            self.GetPos().AddNew(makeVector3(0, 0, 1)),
            1.0f, false, true
        );
    }

    private void OnCloseDoor(HSMessage msg) {
        if(!isOpen) return;  // 既に閉じている

        isOpen = false;
        hsSystemWriteLine("Door: Closing...");

        // 扉を戻す
        self.MovePos(
            self.GetPos().AddNew(makeVector3(0, 0, -1)),
            1.0f, false, true
        );
    }
}

component ButtonController {
    private Item self;
    private Item targetDoor;

    public ButtonController() {
        self = hsItemGetSelf();
        targetDoor = hsItemGet("Door");  // 操作対象の扉
    }

    // ボタンが押された（衝突検出）
    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item collidedItem = hsItemGetByInstanceID(ItemInstanceID);
        if(collidedItem !== null) {
            SendMessageToDoor("OpenDoor");
        }
    }

    private void SendMessageToDoor(string command) {
        if(targetDoor === null) return;

        // メッセージを作成
        HSMessage message = hsCreateSelfMessage(command);

        // メッセージにパラメータを追加（オプション）
        message.AddValue("sender", self.GetName());
        message.AddValue("timestamp", hsSystemGetTimeSeconds());

        // ターゲットにメッセージを送信
        targetDoor.SendMessage(message);

        hsSystemWriteLine("Button: Message sent to " + targetDoor.GetName());
    }
}

