// 【完全版】SetPhysicsWorldPos() の実装ガイド
// 物理オブジェクトを掴んで運ぶパターン（クレーンゲーム等に応用）

component CraneGrabSystem {
    private Item self;
    private Item grabbedObject;              // 現在掴んでいるオブジェクト
    private string physicsNodeName;          // 物理計算対象ノード
    private Vector3 grabOffset;              // 掴む位置のオフセット

    public CraneGrabSystem() {
        self = hsItemGetSelf();
        physicsNodeName = "MainBody";
        grabOffset = makeVector3(0.0f, 0.5f, 0.0f);
    }

    public void Update() {
        if(grabbedObject === null) return;

        // 【重要ステップ1】掴み手の現在位置を取得
        Vector3 grabPoint = self.GetWorldPos();
        grabPoint.x += grabOffset.x;
        grabPoint.y += grabOffset.y;
        grabPoint.z += grabOffset.z;

        // 【重要ステップ2】物体の位置を物理ワールド内で更新
        // SetPhysicsWorldPos() は物理エンジンと連携するメソッド
        // SetPos() との違い：衝突判定が機能し続ける
        grabbedObject.SetPhysicsWorldPos(physicsNodeName, grabPoint);

        // 【重要ステップ3】物理キャッシュをリセット（必ず実行）
        // これを忘れると、物体が重力で落下を始める！
        grabbedObject.ClearPhysicsWorldForce(physicsNodeName);

        // パフォーマンスメモ：
        // - このパターンはUpdate()内で毎フレーム実行される
        // - Vector3の再利用が重要（新規作成を避ける）
        // - 複数オブジェクトを掴む場合は配列で管理
    }

    // 掴み開始
    public void StartGrab(Item target) {
        if(target === null) return;
        if(grabbedObject !== null) EndGrab();  // 既に掴んでいたら放す

        grabbedObject = target;
        grabbedObject.SetCollisionDetection(false);  // 衝突を無効化（オプション）
        hsSystemWriteLine("Grabbed: " + target.GetName());
    }

    // 掴み終了
    public void EndGrab() {
        if(grabbedObject === null) return;

        // 力をリセットして、物体が自然に落ちるようにする
        grabbedObject.ClearPhysicsWorldForce(physicsNodeName);
        grabbedObject.SetCollisionDetection(true);   // 衝突を有効化

        hsSystemWriteLine("Released: " + grabbedObject.GetName());
        grabbedObject = null;
    }

    // 衝突検出時に掴み開始
    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item collidedItem = hsItemGetByInstanceID(ItemInstanceID);
        if(hsInputClickButton(0, "MouseLeft")) {
            StartGrab(collidedItem);
        }
    }
}

