// 物理演算パフォーマンス最適化のベストプラクティス
// 【パフォーマンスの鍵】毎フレーム処理されるUpdate()内で如何に効率的に実行するか

component PhysicsOptimizationTips {
    // ❌ 悪い例：毎フレーム Vector3 を新規作成（メモリ浪費・GC圧迫）
    // 複数オブジェクト × フレームレート(60fps) = 大量のメモリ割り当て
    private void BadVectorHandling(Item obj, float x, float y, float z) {
        for(int i = 0; i < 5; i++) {
            Vector3 newPos = makeVector3(x + i, y, z);  // ← 毎回新規作成 (5回)
            obj.SetPhysicsWorldPos("Body", newPos);
        }
        // 1フレーム = 5個のVector3作成
        // 60fps × 60秒 = 18,000個のオブジェクト生成 (1分で!)
        // → GC圧迫、フレームレート低下
    }

    // ✅ 良い例：Vector3を再利用（メモリ効率的）
    // 【重要】一度だけ作成して、値を上書きする
    private void GoodVectorHandling(Item obj, float x, float y, float z) {
        Vector3 offset = makeVector3(0.0f, 0.0f, 0.0f);  // 1回だけ作成
        for(int i = 0; i < 5; i++) {
            offset.x = x + i;   // 値を上書き
            offset.y = y;
            offset.z = z;
            obj.SetPhysicsWorldPos("Body", offset);
        }
        // 1フレーム = 1個のVector3作成
        // 60fps × 60秒 = 3,600個のオブジェクト生成 (1分で)
        // メモリ使用量を約82%削減！
    }

    // ❌ 悪い例：ClearPhysicsWorldForce() を呼び忘れ
    private void BadGrabWithoutClear(Item hand, Item grabbed) {
        Vector3 handPos = hand.GetWorldPos();
        grabbed.SetPhysicsWorldPos("Body", handPos);
        // ← ClearPhysicsWorldForce() がない！
        // 物体が次フレームで重力に従って落下開始
        // ユーザー体験: 掴んだはずの物体がスルッと落ちる (意図しない動作)
    }

    // ✅ 良い例：ClearPhysicsWorldForce() を呼ぶ
    private void GoodGrabWithClear(Item hand, Item grabbed) {
        Vector3 handPos = hand.GetWorldPos();
        grabbed.SetPhysicsWorldPos("Body", handPos);
        grabbed.ClearPhysicsWorldForce("Body");  // ← 【必須】
        // 【効果】
        // 1. 物体に作用していた重力・速度をリセット
        // 2. 物体が手にしっかり吸い付く
        // 3. SetPhysicsWorldPos() と一対で使う
    }

    // 💡 応用：複数オブジェクト掴みの最適化
    private void OptimizedMultiGrab(list<Item> objects, Vector3 basePos) {
        // メモリ再利用パターン
        Vector3 tempPos = makeVector3(0.0f, 0.0f, 0.0f);
        float yOffset = 0.0f;

        for(int i = 0; i < objects.Count(); i++) {
            Item obj = objects.At(i);
            if(obj === null) continue;

            // 各オブジェクトの位置を計算（Vector3は再利用）
            tempPos.x = basePos.x;
            tempPos.y = basePos.y + yOffset;
            tempPos.z = basePos.z;

            // 物理更新
            obj.SetPhysicsWorldPos("Body", tempPos);
            obj.ClearPhysicsWorldForce("Body");

            yOffset += 0.5f;  // 積み重ねる場合のオフセット
        }
        // N個オブジェクト × 1個Vector3 = メモリ効率最高
    }
}

