// 衝突検出と物理演算の統合パターン
// OnItemTriggerEnter/Stay/Exit と SetPhysicsWorldPos() の連携

component PhysicsCollisionHandler {
    private Item self;
    private Item contactingItem;
    private bool isInContact = false;

    // 衝突開始時（フレーム単位で1度だけ）
    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item collidedItem = hsItemGetByInstanceID(ItemInstanceID);
        if(collidedItem === null) return;

        contactingItem = collidedItem;
        isInContact = true;

        hsSystemWriteLine("Collision Start: " + collidedItem.GetName());

        // 物理演算オブジェクトなら特別処理
        ApplyPhysicsCollisionEffect(collidedItem);
    }

    // 衝突継続中（毎フレーム）
    public void Update() {
        if(!isInContact || contactingItem === null) return;

        // 接触中の物理処理
        // 例：吸い寄せ効果、衝撃力の蓄積等
        ApplyContactForce();
    }

    // 衝突終了時
    public void OnItemTriggerExit(int ItemInstanceID, int NodeIndex) {
        Item separatingItem = hsItemGetByInstanceID(ItemInstanceID);
        if(separatingItem !== null && separatingItem.Equals(contactingItem)) {
            hsSystemWriteLine("Collision End: " + contactingItem.GetName());
            isInContact = false;
            contactingItem = null;
        }
    }

    // 衝突時の物理エフェクト
    private void ApplyPhysicsCollisionEffect(Item physicsObj) {
        // パターン1: 吸い付き効果
        if(physicsObj.GetName().Contains("Magnet")) {
            Vector3 selfPos = self.GetWorldPos();
            physicsObj.SetPhysicsWorldPos("Body", selfPos);
            physicsObj.ClearPhysicsWorldForce("Body");
        }
    }

    // 接触中の力を適用
    private void ApplyContactForce() {
        if(contactingItem === null) return;

        // 物理的な吸い付き継続
        Vector3 selfPos = self.GetWorldPos();
        Vector3 targetPos = contactingItem.GetWorldPos();

        // スムーズに引き寄せる
        float attraction = 0.05f;
        Vector3 direction = targetPos;
        direction.x -= selfPos.x;
        direction.y -= selfPos.y;
        direction.z -= selfPos.z;

        Vector3 newPos = selfPos;
        newPos.x += direction.x * attraction;
        newPos.y += direction.y * attraction;
        newPos.z += direction.z * attraction;

        contactingItem.SetPhysicsWorldPos("Body", newPos);
        contactingItem.ClearPhysicsWorldForce("Body");
    }
}

