component MultiGrabSystem {
    private list<Item> grabbedObjects;
    private list<Vector3> grabOffsets;
    private list<string> physicsNodeNames;
    private int maxGrabCount = 5;
    private Vector3 reusableVec;

    public MultiGrabSystem() {
        grabbedObjects = new list<Item>();
        grabOffsets = new list<Vector3>();
        physicsNodeNames = new list<string>();
        reusableVec = makeVector3(0.0f, 0.0f, 0.0f);
    }

    public void Update() {
        if(grabbedObjects.IsEmpty()) return;

        // バッチ処理：全オブジェクトを効率的に更新
        for(int i = 0; i < grabbedObjects.Count(); i++) {
            Item obj = grabbedObjects.At(i);
            if(obj === null) continue;

            Vector3 offset = grabOffsets.At(i);
            reusableVec.x = hsItemGetSelf().GetWorldPos().x + offset.x;
            reusableVec.y = hsItemGetSelf().GetWorldPos().y + offset.y;
            reusableVec.z = hsItemGetSelf().GetWorldPos().z + offset.z;

            obj.SetPhysicsWorldPos(physicsNodeNames.At(i), reusableVec);
            obj.ClearPhysicsWorldForce(physicsNodeNames.At(i));
        }
    }

    public bool StartGrab(Item target, Vector3 offset, string nodeName) {
        if(target === null || grabbedObjects.Contains(target)) return false;
        if(grabbedObjects.Count() >= maxGrabCount) return false;

        grabbedObjects.Add(target);
        grabOffsets.Add(offset);
        physicsNodeNames.Add(nodeName);
        return true;
    }

    public void ReleaseAll() {
        for(int i = 0; i < grabbedObjects.Count(); i++) {
            grabbedObjects.At(i).ClearPhysicsWorldForce(physicsNodeNames.At(i));
        }
        grabbedObjects.Clear();
        grabOffsets.Clear();
        physicsNodeNames.Clear();
    }
}

