// 反発フィールドパターン
component RepulsionField {
    private Item self;
    private list<Item> affectedObjects;
    private float fieldRadius = 5.0f;
    private float repulsionForce = 0.15f;
    private Vector3 reusableDir;

    public RepulsionField() {
        self = hsItemGetSelf();
        affectedObjects = new list<Item>();
        reusableDir = makeVector3(0.0f, 0.0f, 0.0f);
    }

    public void Update() {
        Vector3 selfPos = self.GetWorldPos();

        for(int i = 0; i < affectedObjects.Count(); i++) {
            Item obj = affectedObjects.At(i);
            if(obj === null) continue;

            Vector3 objPos = obj.GetWorldPos();
            reusableDir.x = objPos.x - selfPos.x;
            reusableDir.y = objPos.y - selfPos.y;
            reusableDir.z = objPos.z - selfPos.z;

            float distance = hsMathLength(reusableDir);
            if(distance > fieldRadius || distance < 0.1f) continue;

            float magnitude = distance;
            reusableDir.x /= magnitude;
            reusableDir.y /= magnitude;
            reusableDir.z /= magnitude;

            Vector3 newPos = objPos;
            newPos.x += reusableDir.x * repulsionForce;
            newPos.y += reusableDir.y * repulsionForce;
            newPos.z += reusableDir.z * repulsionForce;

            obj.SetPhysicsWorldPos("Body", newPos);
        }
    }

    public void OnItemTriggerEnter(int ItemInstanceID, int NodeIndex) {
        Item obj = hsItemGetByInstanceID(ItemInstanceID);
        if(obj !== null && !affectedObjects.Contains(obj)) {
            affectedObjects.Add(obj);
        }
    }

    public void OnItemTriggerExit(int ItemInstanceID, int NodeIndex) {
        Item obj = hsItemGetByInstanceID(ItemInstanceID);
        if(obj !== null) affectedObjects.Remove(obj);
    }
}

