// 掴み機構の改善版：スムーズな追従（弾性効果付き）
// 【改善点】
// - 直結ではなく、スムーズに吸い寄せる（視覚的に自然）
// - 手が速く動いても物体がワープしない
// - パフォーマンスも最適化

component SmoothGrabSystem {
    private Item grabbedObject = null;
    private Vector3 currentPos;  // 現在位置（再利用）
    private Vector3 targetPos;   // 目標位置（再利用）
    private float followSpeed = 0.2f;  // 追従速度（0.0～1.0）
    private string physicsNodeName = "Body";

    public void Update() {
        if(grabbedObject === null) return;

        // 【パフォーマンス最適化】
        // 毎フレーム GetWorldPos() は1回だけ呼び出し
        targetPos = hsItemGetSelf().GetWorldPos();
        currentPos = grabbedObject.GetWorldPos();

        // スムーズに追従（線形補間）
        // 【効果】
        // - 手と物体の距離に応じて滑らかに吸い寄せられる
        // - followSpeed を調整して、挙動をカスタマイズ可能
        //   (0.1 = ゆっくり、0.5 = 標準、 1.0 = 即座)
        currentPos.x += (targetPos.x - currentPos.x) * followSpeed;
        currentPos.y += (targetPos.y - currentPos.y) * followSpeed;
        currentPos.z += (targetPos.z - currentPos.z) * followSpeed;

        // 物理更新
        grabbedObject.SetPhysicsWorldPos(physicsNodeName, currentPos);
        grabbedObject.ClearPhysicsWorldForce(physicsNodeName);
    }

    public void StartGrab(Item target) {
        if(target === null || grabbedObject === target) return;
        grabbedObject = target;
    }

    public void EndGrab() {
        if(grabbedObject === null) return;
        grabbedObject.ClearPhysicsWorldForce(physicsNodeName);
        grabbedObject = null;
    }
}

Physics_OptimizedBatchGrabbing.code:
// 複数物体の掴み管理：パフォーマンス最適化版
// 【設計】
// - 複数オブジェクトをまとめて効率管理
// - Vector3の再利用でメモリ使用量を最小化
// - Updateは O(n) の単純ループで高速

component OptimizedBatchGrabber {
    private list<Item> grabbedObjects;
    private list<Vector3> offsets;       // 各オブジェクトのオフセット
    private list<string> nodeNames;      // 各オブジェクトのノード名
    private Vector3 reusablePos;         // 【最重要】全オブジェクトで再利用
    private Vector3 grabBasePos;         // 掴み手の基準点
    private int maxGrabCount = 5;

    public OptimizedBatchGrabber() {
        grabbedObjects = new list<Item>();
        offsets = new list<Vector3>();
        nodeNames = new list<string>();
        reusablePos = makeVector3(0.0f, 0.0f, 0.0f);
    }

    public void Update() {
        if(grabbedObjects.IsEmpty()) return;  // 何も掴んでいない

        // 【パフォーマンス】掴み手の位置は1回だけ取得
        grabBasePos = hsItemGetSelf().GetWorldPos();

        // 【最適化】全オブジェクトをバッチ処理
        // メモリ再利用により、複数物体でも GC 圧迫なし
        for(int i = 0; i < grabbedObjects.Count(); i++) {
            Item obj = grabbedObjects.At(i);
            if(obj === null) continue;

            Vector3 offset = offsets.At(i);
            string nodeName = nodeNames.At(i);

            // reusablePos に計算結果を格納
            reusablePos.x = grabBasePos.x + offset.x;
            reusablePos.y = grabBasePos.y + offset.y;
            reusablePos.z = grabBasePos.z + offset.z;

            // 物理更新
            obj.SetPhysicsWorldPos(nodeName, reusablePos);
            obj.ClearPhysicsWorldForce(nodeName);
        }
    }

    public bool GrabObject(Item target, Vector3 offset, string nodeName) {
        if(target === null) return false;
        if(grabbedObjects.Contains(target)) return false;  // 既に掴んでいる
        if(grabbedObjects.Count() >= maxGrabCount) return false;  // 最大数達成

        grabbedObjects.Add(target);
        offsets.Add(offset);
        nodeNames.Add(nodeName);
        return true;
    }

    public bool ReleaseObject(Item target) {
        if(target === null) return false;
        int index = grabbedObjects.IndexOf(target);
        if(index < 0) return false;

        grabbedObjects.RemoveAt(index);
        offsets.RemoveAt(index);
        nodeNames.RemoveAt(index);

        target.ClearPhysicsWorldForce(nodeNames.At(index));
        return true;
    }

    public void ReleaseAll() {
        for(int i = 0; i < grabbedObjects.Count(); i++) {
            grabbedObjects.At(i).ClearPhysicsWorldForce(nodeNames.At(i));
        }
        grabbedObjects.Clear();
        offsets.Clear();
        nodeNames.Clear();
    }
}
